export type SkillToolsOptions = {
  capabilityRecovery?: SessionCapabilityRecovery;
  registry: SkillRegistry;
  visibleRegistry?: SkillRegistry;
  localSkillsRoot: string;
  bundledSkillsRoot?: string;
  skillConfig?: Record<string, Record<string, unknown>>;
  skillEvolutionStore?: SkillEvolutionStore;
  changeManifestStore?: ChangeManifestStore;
};

export function createSkillTools(options: SkillToolsOptions): readonly RegisteredTool[] {
  // Operator management keeps the profile registry; model inspection uses the
  // session registry, including its readiness-adjusted skill definitions.
  const inspectionRegistry = options.visibleRegistry ?? options.registry;
  const visibleRecord = (record: { skillName: string }) => options.visibleRegistry === undefined ||
    inspectionRegistry.get(record.skillName) !== undefined;
  const proposalService = options.skillEvolutionStore !== undefined
    ? new SkillProposalService({
        registry: options.registry,
        localSkillsRoot: options.localSkillsRoot,
        skillEvolutionStore: options.skillEvolutionStore,
        changeManifestStore: options.changeManifestStore
      })
    : undefined;
  const runSkillRead = async (input: SkillReadInput, context?: ToolExecutionContext): Promise<ToolResult> => {
    const skill = getSkill(inspectionRegistry, input.name);
    if (!skill.ok) {
      return skill;
    }
    const foundSkill = skill.skill;
    const result = await readSkillContent(foundSkill, input, options.skillConfig?.[foundSkill.name]);
    options.capabilityRecovery?.observeSkillRead(foundSkill, result, input, context);
    if (result.ok) await options.skillEvolutionStore?.recordSkillViewed({
      skillName: foundSkill.name,
      source: isLoadedSkill(foundSkill) ? foundSkill.sourceKind : undefined,
      provenanceKind: "provenance" in foundSkill ? foundSkill.provenance?.kind : undefined,
      resource: input.path !== undefined
    });
    return result;
  };
  const runSkillView = runSkillRead;
  const runSkillSearch = async (input: SkillSearchInput): Promise<ToolResult> => {
    if (!isNonEmptyString(input.query)) {
      return {
        ok: false,
        content: "skill.search requires a non-empty query.",
        metadata: {
          code: "skill-search-query-required"
        }
      };
    }

    const skill = getSkill(inspectionRegistry, input.name);
    if (!skill.ok) {
      return skill;
    }
    if (!isLoadedSkill(skill.skill)) {
      return {
        ok: false,
        content: "skill.search requires a loaded file-backed skill.",
        metadata: {
          code: "skill-search-unloaded-skill",
          name: skill.skill.name
        }
      };
    }

    return searchSkillContent(skill.skill, input);
  };

  return [
    {
      name: "skill.list",
      description: "List available skills with source and category metadata.",
      inputSchema: {
        type: "object",
        properties: {
          category: { type: "string", description: "Optional exact category. Omit or leave blank to list all visible skills." }
        }
      },
      riskClass: "read-only-local",
      toolsets: ["core", "research"],
      progressLabel: "listing skills",
      maxResultSizeChars: 12_000,
      isAvailable: () => true,
      run: async (input: { category?: string }) => {
        const visibleCatalog = inspectionRegistry.catalog();
        const category = input.category?.trim() || undefined;
        const categories = [...new Set(visibleCatalog.map((skill) => skill.category))].sort();
        const catalog = visibleCatalog.filter((skill) => category === undefined || skill.category === category);

        return {
          ok: true,
          content: catalog.length === 0
            ? visibleCatalog.length === 0
              ? "No skills are visible in this session."
              : `No skills match category ${JSON.stringify(category)}. ${visibleCatalog.length} skills are visible. Available categories: ${categories.join(", ")}. Omit category to list all visible skills.`
            : `Showing ${catalog.length} of ${visibleCatalog.length} visible skills.\n` + catalog
                .map((skill) => `${skill.name}\t${skill.category}\t${skill.sourceKind ?? "runtime"}\t${skill.description}`)
                .join("\n"),
          metadata: {
            count: catalog.length,
            totalVisible: visibleCatalog.length,
            category: category ?? null,
            categories,
            skills: catalog
          }
        };
      }
    },
    {
      name: "skill.read",
      description: "Read selected skill instructions, contracts, metadata, or a skill-local resource. Prefer this over skill.view.",
      inputSchema: {
        type: "object",
        properties: {
          name: { type: "string" },
          path: { type: "string", description: "Optional skill-local resource path. A resource path takes precedence over mode; omit for root instructions." },
          mode: { type: "string", enum: ["contract", "full"], description: "Root instruction format. Ignored for resource paths, which always return resource content." }
        },
        required: ["name"]
      },
      riskClass: "read-only-local",
      toolsets: ["core", "research"],
      progressLabel: "reading skill",
      maxResultSizeChars: 24_000,
      isAvailable: () => true,
      run: runSkillRead
